  const infos = () => db().phInfo, batches = () => db().phBatches, pops = () => db().phOps, rxs = () => db().phRx, insurers = () => db().phInsurers, pats = () => db().phPatients, live = o => o.status !== 'Annulé', z = n => String(n).padStart(2, '0');
  const eps = .0005, rd = (n, c) => M.round(n, c || db().settings.currency), num = v => parseFloat(String(v).replace(',', '.')) || 0, cur = () => db().settings.currency;
  PH.info = pid => infos().find(i => i.pid === pid) || null; PH.batch = id => batches().find(b => b.id === id); PH.op = id => pops().find(o => o.id === id); PH.rx = id => rxs().find(r => r.id === id); PH.insurer = id => insurers().find(i => i.id === id);
  PH.patient = cid => pats().find(p => p.clientId === cid) || null;
  const client = id => db().clients.find(c => c.id === id), cname = id => { const c = client(id); return c ? c.name : '—'; }, pname = pid => { const p = S.get(pid); return p ? p.name : '(supprimé)'; };
