      let need = m.qty; const out = []; Object.entries(per).forEach(([b, q]) => { if (need <= eps || q <= eps) return; const t = Math.min(q, need); out.push({ b, q: Math.round(t * 1000) / 1000 }); need -= t; }); if (out.length) m.alloc = out;
