    if (f.assign) { const u = PH.summary()[p.id]; if (!u || f.qty > u.unbatched + eps) return null; } else S.move({ pid: p.id, qty: f.qty, type: 'in', cost: f.cost || 0, supplierId: f.supplierId || '', ref: f.lot, note: 'Lot ' + f.lot, date: b.date, alloc: [] });
